   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for X,Y in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
     if 0<=X<R and 0<=Y<C and a[X][Y]==1 and (X,Y) not in seen: seen.add((X,Y));q.append((X,Y))
   comps.append((comp, any(x in (0,R-1) or y in (0,C-1) for x,y in comp)))
[(len(x),edge, min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x)) for x,edge in comps]
